using System; using System.Configuration; using System.Data; using System.Data.SqlClient; using System.Security.Cryptography; using System.Web; using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp { public partial class ForgotPasswordPage : BasePage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object SendResetLink(string email) { SecurityHelper.ValidateCsrfOrThrow(); var table = DbHelper.ExecuteDataTable("SELECT TOP 1 UserID, Email FROM Users WHERE Email = @Email AND IsActive = 1 AND IsDeleted = 0", CommandType.Text, new SqlParameter("@Email", email ?? string.Empty)); if (table.Rows.Count == 1) { var userId = Convert.ToInt32(table.Rows[0]["UserID"]); var tokenBytes = new byte[48]; using (var rng = RandomNumberGenerator.Create()) { rng.GetBytes(tokenBytes); } var rawToken = Convert.ToBase64String(tokenBytes); DbHelper.ExecuteNonQuery(@"INSERT INTO PasswordResetTokens (UserID, TokenHash, ExpiresAt, IsUsed, CreatedDate) VALUES (@UserID, @TokenHash, DATEADD(MINUTE, @Minutes, GETUTCDATE()), 0, GETUTCDATE())", CommandType.Text, new SqlParameter("@UserID", userId), new SqlParameter("@TokenHash", PasswordHasher.HashPassword(rawToken)), new SqlParameter("@Minutes", int.Parse(ConfigurationManager.AppSettings["ResetTokenMinutes"] ?? "30"))); var url = (ConfigurationManager.AppSettings["applicationUrl"] ?? string.Empty).TrimEnd('/') + "/ResetPassword.aspx?token=" + HttpUtility.UrlEncode(rawToken); EmailService.Send(email, "WAMO Password Reset", "<p>Click the link below to reset your password:</p><p><a href='" + url + "'>Reset Password</a></p>"); AuditLogger.Log(userId, "PASSWORD_RESET", "Authentication", "ForgotPassword.aspx", null, null, "Reset token generated"); } return new { success = true, message = "If the email address exists, a reset link has been sent." }; } } }
